{
    RemoveEvent( pFrame, pData, nEvent );
}
void SalGenericDisplay::ProcessEvent( SalUserEvent aEvent )
{
    aEvent.m_pFrame->CallCallback( aEvent.m_nEvent, aEvent.m_pData );
}
